cat > src/lib/format.ts <<'EOF'
const MIN = 60_000
const HOUR = 60 * MIN
const DAY = 24 * HOUR

export function startOfDay(ts: number) {
  const d = new Date(ts)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

export function formatListDate(ts: number, now = Date.now()) {
  const d = new Date(ts)
  const n = new Date(now)
  if (startOfDay(ts) === startOfDay(now)) {
    return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
  }
  if (d.getFullYear() === n.getFullYear()) {
    return d.toLocaleDateString([], { month: 'short', day: 'numeric' })
  }
  return d.toLocaleDateString([], { month: 'numeric', day: 'numeric', year: '2-digit' })
}

export function relative(ts: number, now = Date.now()) {
  const diff = now - ts
  const future = diff < 0
  const abs = Math.abs(diff)
  let out: string
  if (abs < MIN) out = future ? 'in a moment' : 'just now'
  else if (abs < HOUR) {
    const m = Math.round(abs / MIN)
    out = `${m} minute${m === 1 ? '' : 's'}`
  } else if (abs < DAY) {
    const h = Math.round(abs / HOUR)
    out = `${h} hour${h === 1 ? '' : 's'}`
  } else {
    const d = Math.round(abs / DAY)
    out = `${d} day${d === 1 ? '' : 's'}`
  }
  if (abs < MIN) return out
  return future ? `in ${out}` : `${out} ago`
}

export function formatFullDate(ts: number, now = Date.now()) {
  const d = new Date(ts)
  const date = d.toLocaleDateString([], {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    year: d.getFullYear() === new Date(now).getFullYear() ? undefined : 'numeric',
  })
  const time = d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
  return `${date}, ${time} (${relative(ts, now)})`
}

export function formatLongDate(ts: number) {
  return new Date(ts).toLocaleString([], {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  })
}

export function formatScheduleLabel(ts: number) {
  const d = new Date(ts)
  return d.toLocaleString([], { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })
}

export function formatSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}

export const time = { MIN, HOUR, DAY }

/** Returns a timestamp for a specific hour on the day `offsetDays` from today */
export function atHour(offsetDays: number, hour: number, minute = 0, base = Date.now()) {
  const d = new Date(base)
  d.setDate(d.getDate() + offsetDays)
  d.setHours(hour, minute, 0, 0)
  return d.getTime()
}

export function nextWeekday(weekday: number, hour: number, base = Date.now()) {
  const d = new Date(base)
  const diff = (weekday + 7 - d.getDay()) % 7 || 7
  d.setDate(d.getDate() + diff)
  d.setHours(hour, 0, 0, 0)
  return d.getTime()
}
EOF
cat > src/lib/html.ts <<'EOF'
export function stripHtml(html: string) {
  return html
    .replace(/<(br|\/p|\/div|\/li|\/h\d)[^>]*>/gi, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim()
}

export function escapeHtml(s: string) {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
}

const ALLOWED = new Set([
  'P', 'DIV', 'BR', 'B', 'STRONG', 'I', 'EM', 'U', 'S', 'STRIKE', 'UL', 'OL', 'LI', 'A', 'SPAN',
  'BLOCKQUOTE', 'H1', 'H2', 'H3', 'H4', 'TABLE', 'TBODY', 'THEAD', 'TR', 'TD', 'TH', 'HR', 'CODE', 'PRE', 'FONT', 'SMALL', 'IMG',
])

/** Minimal allow-list sanitizer for locally composed HTML */
export function sanitizeHtml(html: string) {
  if (typeof DOMParser === 'undefined') return html
  const doc = new DOMParser().parseFromString(`<div>${html}</div>`, 'text/html')
  const root = doc.body.firstElementChild as HTMLElement
  const walk = (el: Element) => {
    for (const child of Array.from(el.children)) {
      if (!ALLOWED.has(child.tagName)) {
        if (child.tagName === 'SCRIPT' || child.tagName === 'STYLE' || child.tagName === 'IFRAME') {
          child.remove()
          continue
        }
        const frag = doc.createDocumentFragment()
        while (child.firstChild) frag.appendChild(child.firstChild)
        child.replaceWith(frag)
        walk(el)
        return
      }
      for (const attr of Array.from(child.attributes)) {
        const name = attr.name.toLowerCase()
        const keep =
          (name === 'href' && /^(https?:|mailto:)/i.test(attr.value)) ||
          (name === 'src' && /^data:image\//i.test(attr.value)) ||
          name === 'class' ||
          (name === 'style' && !/url\(|expression/i.test(attr.value))
        if (!keep) child.removeAttribute(attr.name)
      }
      if (child.tagName === 'A') {
        child.setAttribute('target', '_blank')
        child.setAttribute('rel', 'noopener noreferrer')
      }
      walk(child)
    }
  }
  walk(root)
  return root.innerHTML
}

export function textToHtml(text: string) {
  return text
    .split(/\n{2,}/)
    .map((p) => `<p>${escapeHtml(p).replace(/\n/g, '<br>')}</p>`)
    .join('')
}
EOF
cat > src/lib/avatar.ts <<'EOF'
const PALETTE = [
  '#1a73e8', '#d93025', '#188038', '#e37400', '#9334e6', '#007b83', '#c5221f', '#b31412',
  '#1967d2', '#0d652d', '#a142f4', '#e8710a', '#12b5cb', '#5f6368', '#f439a0', '#3949ab',
]

export function colorFor(key: string) {
  let h = 0
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0
  return PALETTE[h % PALETTE.length]
}

export function initials(name: string) {
  const clean = name.replace(/[^\p{L}\p{N} ]/gu, '').trim()
  if (!clean) return '?'
  return clean[0].toUpperCase()
}

export function firstName(name: string) {
  return name.split(/\s+/)[0]
}
