        (a): Attachment => ({ id: `a${++aid}`, name: a.name, size: a.kb * 1024, kind: kindOf(a.name), hue: a.hue ?? (aid * 47) % 360 }),
      ),
    }))
    const fromMeLast = messages[messages.length - 1].from.email === ME.email
    threads.push({
      id,
      subject: s.subject,
      messages,
      inbox: s.inbox ?? true,
      trash: s.trash ?? false,
      spam: s.spam ?? false,
      starred: s.starred ?? false,
      important: s.important ?? false,
