      const deliver = (d: Draft, date: number): string => {
        const threads = { ...get().threads }
        const msg = draftToMessage(d, date)
        let threadId: string
        const existing = d.threadId ? threads[d.threadId] : undefined
        if (existing && d.replyMode !== 'forward') {
