          ),
        snooze: (ids, until) => mutate((t) => mapIds(t, ids, () => ({ snoozeUntil: until, inbox: true }))),
        unsnooze: (ids) => mutate((t) => mapIds(t, ids, () => ({ snoozeUntil: undefined, inbox: true }))),
        deleteMessage: (threadId, messageId) =>
